class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        limit = min(map(len, strs))
        for i in range(limit):
            ch = strs[0][i]
            if any(word[i] != ch for word in strs[1:]):
                return strs[0][:i]
        return strs[0][:limit]

class Solution {
    public String longestCommonPrefix(String[] strs) {
        int limit = strs[0].length();
        for (String word : strs) limit = Math.min(limit, word.length());
        for (int i = 0; i < limit; i++) {
            char ch = strs[0].charAt(i);
            for (int j = 1; j < strs.length; j++) {
                if (strs[j].charAt(i) != ch) return strs[0].substring(0, i);
            }
        }
        return strs[0].substring(0, limit);
    }
}

