        for(int r=0;r<n;r++)for(int c=r+1;c<n;c++){int t=matrix[r][c];matrix[r][c]=matrix[c][r];matrix[c][r]=t;}
        for(int[] row:matrix)for(int l=0,r=n-1;l<r;l++,r--){int t=row[l];row[l]=row[r];row[r]=t;}
    }
}

from typing import List
from collections import defaultdict

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = defaultdict(list)
        for word in strs: groups[''.join(sorted(word))].append(word)
        return list(groups.values())

import java.util.*;

class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        Map<String,List<String>> groups=new HashMap<>();
        for(String word:strs){char[] chars=word.toCharArray();Arrays.sort(chars);String key=new String(chars);groups.computeIfAbsent(key,k->new ArrayList<>()).add(word);}
        return new ArrayList<>(groups.values());
    }
}

class Solution:
    def myPow(self, x: float, n: int) -> float:
        exponent = n
        if exponent < 0: x, exponent = 1 / x, -exponent
        result = 1.0
        while exponent:
            if exponent & 1: result *= x
            x *= x; exponent >>= 1
        return result

class Solution {
    public double myPow(double x, int n) {
        long exponent=n;
        if(exponent<0){x=1.0/x;exponent=-exponent;}
        double result=1.0;
        while(exponent>0){if((exponent&1L)==1L)result*=x;x*=x;exponent>>=1;}
        return result;
    }
}
